  describe "entries claimed only through a sent invoice's lines" do
    let(:line_only_company) { create(:company) }
    let(:line_only_client) { create(:client, company: line_only_company) }
    let(:line_only_project) { create(:project, client: line_only_client, billable: true) }
    let(:line_only_user) { create(:user, current_workspace_id: line_only_company.id) }

    # Lines are written under the legacy owner, then ownership moves to the
    # prepared store with no reservation row for either entry, as after a sent
    # invoice's added lines pass admit.
    def line_only_prepared_copy(entry)
      Timekeeping::LocalEntry.create!(id: entry.id, company_id: line_only_company.id, user_id: line_only_user.id,
                                      project_id: line_only_project.id, work_date: Date.current, duration: 60.0,
                                      bill_status: "unbilled")
    end

    it "refuses a draft's prepare for an entry on a sent invoice's direct line or grouped line and writes nothing" do
      direct = create(:timesheet_entry, user: line_only_user, project: line_only_project, bill_status: "unbilled")
      sent = create(:invoice, company: line_only_company, client: line_only_client, status: :sent)
      line = create(:invoice_line_item, invoice: sent, timesheet_entry: direct, rate: 100, quantity: 60)
      grouped = create(:invoice_line_item_time_entry, invoice_line_item: line).timesheet_entry
      InvoiceEntryHolding.where(company_id: line_only_company.id, invoice_id: sent.id).delete_all
      draft = create(:invoice, company: line_only_company, client: line_only_client, status: :draft)
      free = create(:timesheet_entry, user: line_only_user, project: line_only_project, bill_status: "unbilled")
      [direct, grouped, free].each { |entry| line_only_prepared_copy(entry) }
      TimekeepingOwnership.current.update!(owner: "monolith", monolith_store: "prepared", handoff_step: nil)
      company_id = line_only_company.id
      counts = lambda do
        %w[reservations invoice_operations entry_outbox_items].map do |table|
          ApplicationRecord.connection.select_value(
            ApplicationRecord.sanitize_sql_array(["SELECT COUNT(*) FROM #{table} WHERE company_id = ?", company_id])
          ).to_i
        end
      end
      before = counts.call
      request = Invoices::ReservationRequest.new(
        company_id:, invoice_id: draft.id, operation_id: SecureRandom.uuid,
        generation: TimekeepingOwnership.current.generation, disposition: "active",
        entries: [direct.id, grouped.id, free.id]
      )

      # "A second kept invoice on the same entry fails with \"entry is on another invoice\""
      outcome = described_class.new.prepare(request)

      expect(outcome.state).to eq("refused")
      expect(outcome.conflicts).to contain_exactly(
        { entry_id: direct.id, reason: "on_another_invoice" }, { entry_id: grouped.id, reason: "on_another_invoice" }
      )
      expect(counts.call).to eq(before)
    end
  end

  describe "retained row beside another kept invoice's line" do
    let(:retained_line_company) { create(:company) }
    let(:retained_line_client) { create(:client, company: retained_line_company) }
    let(:retained_line_project) { create(:project, client: retained_line_client, billable: true) }
    let(:retained_line_user) { create(:user, current_workspace_id: retained_line_company.id) }

    # A discarded sent invoice keeps the entry as a retained row; a live sent
    # invoice then claims it only through a line its admit let through. A
    # third, draft invoice must still be refused.
    it "refuses a draft's prepare for an entry another kept invoice claims through its line while a discarded invoice retains it" do
      entry = create(:timesheet_entry, user: retained_line_user, project: retained_line_project, bill_status: "unbilled")
      discarded = create(:invoice, company: retained_line_company, client: retained_line_client, status: :sent)
      discarded.update_columns(discarded_at: Time.current)
      sent = create(:invoice, company: retained_line_company, client: retained_line_client, status: :sent)
      create(:invoice_line_item, invoice: sent, timesheet_entry: entry, rate: 100, quantity: 60)
      InvoiceEntryHolding.where(company_id: retained_line_company.id, invoice_id: sent.id).delete_all
      draft = create(:invoice, company: retained_line_company, client: retained_line_client, status: :draft)
      Timekeeping::LocalEntry.create!(id: entry.id, company_id: retained_line_company.id, user_id: retained_line_user.id,
                                      project_id: retained_line_project.id, work_date: Date.current, duration: 60.0,
                                      bill_status: "unbilled")
      connection = ApplicationRecord.connection
      connection.execute(ApplicationRecord.sanitize_sql_array([<<~SQL.squish, retained_line_company.id, entry.id, discarded.id, SecureRandom.uuid, Time.current]))
        INSERT INTO reservations (company_id, entry_id, invoice_id, operation_id, state, disposition, created_at)
        VALUES (?, ?, ?, ?, 'committed', 'retained', ?)
      SQL
      TimekeepingOwnership.current.update!(owner: "monolith", monolith_store: "prepared", handoff_step: nil)
      rows = lambda do
        connection.select_rows(ApplicationRecord.sanitize_sql_array([
          "SELECT entry_id, invoice_id, state, disposition FROM reservations WHERE company_id = ? ORDER BY invoice_id",
          retained_line_company.id
        ]))
      end
      rows_before = rows.call
      request = Invoices::ReservationRequest.new(
        company_id: retained_line_company.id, invoice_id: draft.id, operation_id: SecureRandom.uuid,
        generation: TimekeepingOwnership.current.generation, disposition: "active", entries: [entry.id]
      )

      # "A second kept invoice on the same entry fails with \"entry is on another invoice\""
      outcome = described_class.new.prepare(request)

      expect(outcome.state).to eq("refused")
      expect(outcome.conflicts).to eq([{ entry_id: entry.id, reason: "on_another_invoice" }])
      expect(rows.call).to eq(rows_before)
      expect(connection.select_value(ApplicationRecord.sanitize_sql_array([
        "SELECT COUNT(*) FROM invoice_operations WHERE company_id = ? AND invoice_id = ?", retained_line_company.id, draft.id
      ])).to_i).to eq(0)
    end
  end

  describe "own retained row beside another kept invoice's line" do
    let(:own_retained_company) { create(:company) }
    let(:own_retained_client) { create(:client, company: own_retained_company) }
    let(:own_retained_project) { create(:project, client: own_retained_client, billable: true) }
    let(:own_retained_user) { create(:user, current_workspace_id: own_retained_company.id) }

    # A restored invoice still retains its entries while a sent invoice has
    # since claimed them through a direct and a grouped line its admit let
    # through. Taking them back would put each entry on two kept invoices.
    it "refuses a restored invoice's prepare for its own retained entries another kept invoice claims through lines" do
      direct = create(:timesheet_entry, user: own_retained_user, project: own_retained_project, bill_status: "unbilled")
      sent = create(:invoice, company: own_retained_company, client: own_retained_client, status: :sent)
      line = create(:invoice_line_item, invoice: sent, timesheet_entry: direct, rate: 100, quantity: 60)
      grouped = create(:invoice_line_item_time_entry, invoice_line_item: line).timesheet_entry
      InvoiceEntryHolding.where(company_id: own_retained_company.id, invoice_id: sent.id).delete_all
      restored = create(:invoice, company: own_retained_company, client: own_retained_client, status: :draft)
      connection = ApplicationRecord.connection
      [direct, grouped].each do |entry|
        Timekeeping::LocalEntry.create!(id: entry.id, company_id: own_retained_company.id, user_id: own_retained_user.id,
                                        project_id: own_retained_project.id, work_date: Date.current, duration: 60.0,
                                        bill_status: "unbilled")
        connection.execute(ApplicationRecord.sanitize_sql_array([<<~SQL.squish, own_retained_company.id, entry.id, restored.id, SecureRandom.uuid, Time.current]))
          INSERT INTO reservations (company_id, entry_id, invoice_id, operation_id, state, disposition, created_at)
          VALUES (?, ?, ?, ?, 'committed', 'retained', ?)
        SQL
      end
      TimekeepingOwnership.current.update!(owner: "monolith", monolith_store: "prepared", handoff_step: nil)
      rows = lambda do
        connection.select_rows(ApplicationRecord.sanitize_sql_array([
          "SELECT entry_id, invoice_id, state, disposition FROM reservations WHERE company_id = ? ORDER BY entry_id",
          own_retained_company.id
        ]))
      end
      rows_before = rows.call
      request = Invoices::ReservationRequest.new(
        company_id: own_retained_company.id, invoice_id: restored.id, operation_id: SecureRandom.uuid,
        generation: TimekeepingOwnership.current.generation, disposition: "active", entries: [direct.id, grouped.id]
      )

      # "A second kept invoice on the same entry fails with \"entry is on another invoice\""
      outcome = described_class.new.prepare(request)

      expect(outcome.state).to eq("refused")
      expect(outcome.conflicts).to contain_exactly(
        { entry_id: direct.id, reason: "on_another_invoice" }, { entry_id: grouped.id, reason: "on_another_invoice" }
      )
      expect(rows.call).to eq(rows_before)
    end
  end
end
